#!/usr/bin/env node

"use strict";

const fs = require("fs");
const parseArgs = require("minimist");
const Jibo = require("@jibo/jibo-server-client");

let args = process.argv.slice(2);
const argopts = {
    string: ["credentials", "subsystem", "file", "from", "to", "depends", "changes", "filter"],
    boolean: ["h", "help"]
};
let argv = parseArgs(args, argopts);

function usage() {
    console.log("Usage:", process.argv[1], "[options]");
    console.log("");
    console.log("OPTIONS:");
    console.log("  -h,--help                print this message");
    console.log("  --credentials FILE       path to credentials.json");
    console.log("  --subsystem NAME         subsystem name");
    console.log("  --file FILE              file that contains the update");
    console.log("  --from VERSION           from version");
    console.log("  --to VERSION             to version");
    console.log("  --depends DEPENDENCY     ");
    console.log("  --changes STRING         ");
    console.log("  --filter  STRING         ");
}

if (argv.h || argv.help) {
    usage();
    process.exit(0);
}

if (!argv.credentials) {
    console.log("ERROR: credentials file not specified!");
    usage();
    process.exit(1);
}

if (!argv.subsystem) {
    console.log("ERROR: subsystem not specified!");
    usage();
    process.exit(1);
}

if (!argv.file) {
    console.log("ERROR: file not specified!");
    usage();
    process.exit(1);
}

if (!argv.from) {
    console.log("ERROR: from not specified!");
    usage();
    process.exit(1);
}

if (!argv.to) {
    console.log("ERROR: to not specified!");
    usage();
    process.exit(1);
}

if (!argv.depends) {
    console.log("ERROR: depends not specified!");
    usage();
    process.exit(1);
}

if (!argv.changes) {
    console.log("ERROR: changes not specified!");
    usage();
    process.exit(1);
}

Jibo.config.loadFromPath(argv.credentials);

let update = new Jibo.Update();

let depends = JSON.parse(argv.depends);
let fstream = fs.createReadStream(argv.file);

let params = {
    changes: argv.changes,
    fromVersion: argv.from,
    toVersion: argv.to,
    body: fstream,
    dependencies: depends,
    subsystem: argv.subsystem
};

if (argv.filter) {
    params.filter = argv.filter;
}

update.createUpdate(params, function(err, data) {
    if (err) {
        console.log("Error!", err, err.stack);
    } else {
        console.log("OK!", data);
    }
});
